import 'package:flutter/material.dart'; import 'package:get/get.dart'; import '../controllers/legal_controller.dart';
class LegalView extends StatelessWidget { const LegalView({super.key}); @override Widget build(BuildContext context){ if(!Get.isRegistered<LegalController>()) Get.put(LegalController()); final c=Get.find<LegalController>(); return Obx(() => ListView(padding: const EdgeInsets.all(20), children: [Text('Legal Function', style: Theme.of(context).textTheme.headlineSmall), ...c.status.entries.map((e)=>ListTile(title: Text(e.key), trailing: Text('${e.value}')))]));}}
